CREATE TABLE IF NOT EXISTS  dm_otc_n.bi_otc_cust_index( 
	 company_name string COMMENT '公司名称' , company_id string COMMENT '公司ID/USCC' , contact_sales string COMMENT '对接销售' , sales_login string COMMENT '销售LOGIN' , cust_hold_win_rate string COMMENT '客户持仓总胜率' , cust_win_rate string COMMENT '客户胜率' , margin_ratio string COMMENT '履保比例' , margin_call_line string COMMENT '追保线' , margin_grade string COMMENT '履保分级' , risk_test_data string COMMENT '风险压测数据' , outst_margin_amount string COMMENT '存续履保交易规模(万元)' , used_quota string COMMENT '已用额度(万元)' , approved_quota string COMMENT '获批额度(万元)' , approved_busi_type string COMMENT '获批的业务类型' , margin_call_rate string COMMENT '及时追保完成率' , cust_advance_info string COMMENT '客户垫资情况(如有)' , credit_measure string COMMENT '增信措施(如有)' , cust_satisfaction_score string COMMENT '客户满意度总分' , cust_satisfaction_feedback string COMMENT '客户满意度改进意见' , swap_turnover_rate string COMMENT '互换业务本月换手率' , swap_new_principal string COMMENT '互换业务本月新增本金(万元)' , swap_outst_month_end string COMMENT '互换业务上月末存续(亿元)' , swap_platform_fee string COMMENT '互换业务平台费(万元)' , swap_bond_interest string COMMENT '互换业务券息(万元)' , swap_commission string COMMENT '互换业务佣金(万元)' ) COMMENT 'OTC客户指标表' PARTITIONED BY ( busi_date string COMMENT '业务日期' ) STORED AS ORC